from pathlib import Path
p=Path('index.html');s=p.read_text()
a=s.index('function finalizeRunRecord(){');b=s.index('$("SAVE_LOG").onclick=finalizeRunRecord;',a)
fn=r'''function finalizeRunRecord(){if(!pendingSession)return;syncPendingFromForm();if(pendingSession.v4Context?.isNew&&!pendingSession.shopId){let nm=String($("LOG_NEW_SHOP")?.value||"").trim();if(!nm){showMiniToast("新規店舗名を入れてね");$("LOG_NEW_SHOP")?.focus();return}let sh=addShopByName(nm);if(!sh){showMiniToast("店舗名を登録できなかったよ");return}pendingSession.shopId=sh.id;pendingSession.v4Context.shopId=sh.id;pendingSession.v4Context.shopName=sh.name;pendingSession.v4Context.isNew=false;v4Context={...v4Context,shopId:sh.id,shopName:sh.name,isNew:false};refreshShopSelect(sh.id)}if(!pendingSession.playedG){showMiniToast("実戦Gが0だよ");return}let cx=pendingSession.v4Context||{},cxShop=shopName(pendingSession.shopId);if(cxShop&&pendingSession.tableNo&&M[pendingSession.machine]&&!v4MachineForTable(cxShop,pendingSession.date,pendingSession.tableNo)){v4LayoutOverrides.push({shopName:cxShop,tableNo:String(pendingSession.tableNo),machine:pendingSession.machine,fromDate:pendingSession.date,createdAt:Date.now()});v4LayoutOverrides=v4LayoutOverrides.slice(-1000)}let q=pendingSession.q,key=pendingSession.machine,g=pendingSession.playedG,active=financeInputActive(pendingSession),fin=active?runFinance(pendingSession):null,sh=shops.find(x=>String(x.id)===String(pendingSession.shopId));if(sh&&active){let changed=false;if(fin.loanCoinsPer1000&&+sh.loanCoinsPer1000!==fin.loanCoinsPer1000){sh.loanCoinsPer1000=fin.loanCoinsPer1000;changed=true}if(fin.exchangeCoinsPer1000&&+sh.exchangeCoinsPer1000!==fin.exchangeCoinsPer1000){sh.exchangeCoinsPer1000=fin.exchangeCoinsPer1000;changed=true}if(changed)sh.financeRateUpdatedAt=Date.now()}let oldA=hasActual(pendingSession)?+pendingSession.actualDiff:null,oldC=hasCash(pendingSession)?+pendingSession.cashDiff:null,oldS=hasSavedDelta(pendingSession)?+pendingSession.savedCoinDelta:null;let rec={...clone(pendingSession),entryType:entryTypeOf(pendingSession),tagIds:sessionTagIds(pendingSession),id:editingSessionId??sessionSeq++,createdAt:+pendingSession.createdAt||Date.now(),updatedAt:Date.now(),expectedSetting:expectedSetting(q),expectedRate:expectedRatePct(key,q),expectedDiff:expectedDiffCoins(key,q,g),actualDiff:active?(Number.isFinite(fin.actualDiff)?fin.actualDiff:null):oldA,cashDiff:active?(Number.isFinite(fin.cashDiff)?fin.cashDiff:null):oldC,savedCoinDelta:active?(Number.isFinite(fin.savedCoinDelta)?fin.savedCoinDelta:null):oldS};if(fin)Object.assign(rec,{financeVersion:2,loanCoinsPer1000:fin.loanCoinsPer1000,exchangeCoinsPer1000:fin.exchangeCoinsPer1000,savedInvestCoins:fin.savedInvestCoins,cashInvestYen:fin.cashInvestYen,collectedCoins:fin.collectedCoins,exchangedYen:fin.exchangedYen,exchangeUsedCoins:fin.exchangeUsedCoins,exchangeUsedCoinsOverride:numberOrNull(pendingSession.exchangeUsedCoinsOverride),cashBorrowedCoins:fin.cashBorrowedCoins,totalInvestCoins:fin.totalInvestCoins,valueProfit:fin.valueProfit});if(editingSessionId!=null){let i=sessions.findIndex(x=>String(x.id)===String(editingSessionId));if(i>=0)sessions[i]=rec;else sessions.push(rec)}else sessions.push(rec);pendingSession=null;editingSessionId=null;autoSaveState();renderCalendar();renderStoreManagement();showMiniToast("稼働記録に保存したよ");renderRunLog()}
'''
s=s[:a]+fn+s[b:]
old='pendingSession=clone(r);editingSessionId=r.id;setPage("runlog")'
new='pendingSession=clone(r);editingSessionId=r.id;markLazyPageDirty("runlog");setPage("runlog");requestAnimationFrame(()=>$("LOG_FORM")?.scrollIntoView({behavior:"smooth",block:"start"}))'
if old not in s: raise SystemExit('edit marker')
s=s.replace(old,new,1)
if 'window.V4_TEST={predictStore:' not in s: raise SystemExit('test export marker')
s=s.replace('window.V4_TEST={predictStore:','window.V4_TEST={runFinance,predictStore:',1)
p.write_text(s)
